    // 成功路径：发布物实际调度链写出合法 JSON、无 tmp 残留，POSIX 权限为 0600。
    let response = makeRes();
    await select.handler(
      fakeReq({
        method: "POST",
        body: JSON.stringify({
          provider: OPENCODE_GO_PROVIDER,
          adapterName: OPENCODE_GO_ADAPTER_ID,
