  it("路由写侧经注入（B1 值边清零，同级短径，不走旧深径）", () => {
    expect(reportsSrc.includes('"../schedule/interface.ts"')).toBe(true);
    expect(reportsSrc.includes("context.presetLastRunForNewlyEnabled")).toBe(true);
